window.QUIZ_DATA = {"chapter": 2, "title": "Chapter 2 — Security", "sections": [{"id": "2.1", "title": "Security Measures and Their Purposes", "file": "2.1 Security Measures and Their Purposes.html", "count": 41}, {"id": "2.2", "title": "Windows OS Security Settings", "file": "2.2 Configure and Apply Basic Microsoft Windows OS Security Settings.html", "count": 36}, {"id": "2.3", "title": "Wireless Security Protocols", "file": "2.3 Wireless Security Protocols and Authentication Methods.html", "count": 8}, {"id": "2.4", "title": "Malware and Adware Types", "file": "2.4 Malware and Adware Types.html", "count": 22}, {"id": "2.5", "title": "Social Engineering and Threats", "file": "2.5 Social Engineering Attacks, Threats, and Vulnerabilities.html", "count": 28}, {"id": "2.6", "title": "Malware Investigation and Remediation", "file": "2.6 Malware Investigation and Remediation.html", "count": 10}, {"id": "2.7", "title": "Encryption and Security Best Practices", "file": "2.7 Data-at-Rest Encryption and Security Best Practices.html", "count": 26}, {"id": "2.8", "title": "Mobile Device Hardening", "file": "2.8 Mobile Device Hardening Techniques.html", "count": 15}, {"id": "2.9", "title": "Data Destruction and Sanitization", "file": "2.9 Data Destruction and Sanitization.html", "count": 13}, {"id": "2.10", "title": "Router and Firewall Settings", "file": "2.10 Router, Wireless, and Firewall Settings.html", "count": 14}, {"id": "2.11", "title": "Browser Security and Configuration", "file": "2.11 Browser Security and Configuration.html", "count": 18}], "terms": [{"id": "2.1-0", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Bollards", "definition": "Prevent access — with limits. Channel people through a specific access point while keeping out other things. Allow people; prevent cars and trucks. Identify safety concerns and prevent injuries. Can be used to an extreme: concrete barriers, bollards, even moats.", "scenario": "Cars keep pulling into the pedestrian plaza in front of the lobby. You need posts that let people walk through but stop vehicles. What should you install?"}, {"id": "2.1-1", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Access control vestibule", "definition": "A two-door entry system that controls traffic one person or group at a time.", "scenario": "Visitors must badge in, wait in a small room, and badge a second door before reaching the lobby so only one group enters at a time. What is that entry called?"}, {"id": "2.1-2", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Badge reader", "definition": "Magnetic swipe, RFID, or NFC — many different identification methods for different applications.", "scenario": "Employees tap a card at the office door instead of using a metal key. What device is reading the card?"}, {"id": "2.1-3", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Video surveillance", "definition": "Can replace physical guards. Camera features are important — object detection can identify a license plate or a person’s face. Often many different cameras networked together and recorded over time.", "scenario": "After hours someone circled the loading dock. Security wants recorded camera footage, not a guard standing there all night. What control is that?"}, {"id": "2.1-4", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Alarm systems", "definition": "Circuit-based. A circuit is opened or closed — door, window, fence. Useful on the perimeter.", "scenario": "A warehouse door contact should trip if the door opens after close. What kind of system is that?"}, {"id": "2.1-5", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Motion sensors", "definition": "Motion detection that identifies movement without a camera.", "scenario": "A dark hallway has no camera, but you still want an alert if someone walks through. What sensor do you use?"}, {"id": "2.1-6", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Door locks", "definition": "Conventional — lock and key, deadbolt (physical bolt) Electronic — keyless PIN, token-based, RFID badge, magnetic swipe, or key fob Biometric — hand, finger, or retina Multi-factor — smart card and PIN", "scenario": "The server room door needs a lock — key, PIN, badge, or fingerprint are all on the table. What physical control is this?"}, {"id": "2.1-7", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Equipment locks", "definition": "Data center hardware is usually managed by different groups. Responsibility lies with the owner. Racks can be installed side-to-side. Enclosed cabinets with locks — ventilation on front, back, top, and bottom.", "scenario": "Two teams share a row of cabinets; each team must keep other techs out of their gear. What do you put on the racks?"}, {"id": "2.1-8", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Security guards and access lists", "definition": "Physical protection at the reception area of a facility. Validates identification of existing employees. Provides guest access.", "scenario": "Front desk staff check employee IDs and sign guests in against a list. What physical control is that?"}, {"id": "2.1-9", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical security", "name": "Fences", "definition": "Build a perimeter — usually very obvious. May not be what you’re looking for.", "scenario": "You need an obvious perimeter around the lot so people cannot wander onto the property. What do you build?"}, {"id": "2.1-10", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Key fobs", "definition": "Small RFID key added to a physical keychain. Replaces a physical key. Commonly used for door locks — proximity operation and contactless.", "scenario": "Staff unlock the side door by holding a small RFID fob near the reader, no metal key. What are they using?"}, {"id": "2.1-11", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Smart cards", "definition": "Certificate-based authentication. Usually requires additional factors. Integrated card reader built into the laptop, or an external USB-connected reader.", "scenario": "Laptops require a certificate on a wallet-sized card plus a PIN in a USB reader. What authentication item is that?"}, {"id": "2.1-12", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Mobile digital key", "definition": "Replaces physical keys with your phone. Many different apps — automobile unlocking and starting, hotel or office door locks, doors at home. Better authentication than a physical key. Must have access to the phone; unlock for verification.", "scenario": "Hotel guests open the room with their phone instead of a plastic card. What kind of key is that?"}, {"id": "2.1-13", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Keys", "definition": "Some doors may not have an electronic lock — rarely used. Standalone locks: safe, storage bin, cabinet. Use a key cabinet with formal check-in/check-out and a well-defined storage location. Allows for auditing and timestamps.", "scenario": "The safe still uses a traditional metal key that is checked out from a cabinet with a log. What are you managing?"}, {"id": "2.1-14", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Biometrics", "definition": "Biometric authentication usually stores a mathematical representation of your biometric — your actual fingerprint isn’t usually saved.", "scenario": "The door unlocks from a fingerprint or face scan rather than a password. What class of authentication is that?"}, {"id": "2.1-15", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Retina scanner", "definition": "Reads the unique capillary structure in the back of the eye.", "scenario": "Access requires scanning the unique pattern of blood vessels at the back of the eye. Which biometric is that?"}, {"id": "2.1-16", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Fingerprint scanner", "definition": "Common on phones, laptops, and door access systems.", "scenario": "Phones and the lab door both unlock from a finger on a sensor. Which biometric is that?"}, {"id": "2.1-17", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Palm print scanner", "definition": "Measures the shape of the hand and fingers.", "scenario": "The data center turnstile measures the shape of the whole hand, not just one finger. Which scanner is that?"}, {"id": "2.1-18", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Facial recognition technology (FRT)", "definition": "Authenticate using a common biometric feature — your face. Creates a digital “key” from your facial features using a laser dot projector, infrared camera, and 3D facial map.", "scenario": "Windows Hello and the phone lock both build a 3D map of the user’s face with IR cameras. Which technology is that?"}, {"id": "2.1-19", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Voice recognition technology", "definition": "Uses an individual’s voice as a key. The system is “trained” by speaking phrases; results are evaluated and stored. Verify yourself with a different phrase — voice recognition software listens for the original speaker.", "scenario": "A call center verifies the speaker by asking them to say a new phrase after training on their voice. Which biometric is that?"}, {"id": "2.1-20", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Lighting", "definition": "More light means more security. Attacks avoid the light. Easier to see when lit. Non-IR cameras can see better.", "scenario": "The parking garage is too dark for regular cameras and attackers like the shadows. What cheap physical control do you add?"}, {"id": "2.1-21", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Physical access security", "name": "Magnetometers", "definition": "Passive scanning that detects metal objects. Not useful for non-metal objects — won’t identify ceramic or plastic.", "scenario": "At the lobby you need to catch metal weapons but plastic tools will still pass. What scanner is that?"}, {"id": "2.1-22", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Principle of least privilege", "definition": "Rights and permissions should be set to the bare minimum — you only get what’s needed to complete your objective.", "scenario": "A clerk only needs to print labels, so you refuse admin rights on their PC. Which principle is that?"}, {"id": "2.1-23", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Zero Trust model", "definition": "Many networks are relatively open on the inside — once you’re through the firewall, there are few security controls. Zero Trust is a holistic approach to network security covering every device, every process, and every person.", "scenario": "Even on the office LAN, every user and device must prove itself again before reaching apps. Which model is that?"}, {"id": "2.1-24", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Access control lists (ACLs)", "definition": "Used to allow or deny traffic. Also used for NAT, QoS, etc. Commonly applied on the ingress or egress of a router interface.", "scenario": "The edge router should drop traffic from a guest subnet to the finance VLAN. What are those allow/deny rules called?"}, {"id": "2.1-25", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Multifactor authentication (MFA)", "definition": "Prove who you are using different methods — a memorized password, a mobile app, your GPS location.", "scenario": "Login requires something you know plus something you have, not a password alone. What is that called?"}, {"id": "2.1-26", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Email auth", "definition": "Associate a person with an email address. Validate a person at that email — useful during registration. Verify a user’s email address. Use instead of a password (username is your email).", "scenario": "A new portal sends a link to prove the address really belongs to the user before they set a password. What check is that?"}, {"id": "2.1-27", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Hardware token", "definition": "A physical security device that generates or stores authentication codes to verify a user’s identity when logging into an account or system.", "scenario": "Field techs carry a small physical device that shows a changing login code. What is that device?"}, {"id": "2.1-28", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Authenticator application", "definition": "Pseudo-random token generators — a useful authentication factor. Carry a physical hardware token generator, or use a software-based token generator on your phone. Powerful and convenient.", "scenario": "Users open an app on their phone that shows a rotating code instead of carrying a key fob. What is that app?"}, {"id": "2.1-29", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Short Message Service (SMS)", "definition": "Text messaging — includes more than text these days. A login factor can be sent via SMS to a predefined phone number: provide username and password, phone receives an SMS, input the code into the login form.", "scenario": "After the password, a numeric code is texted to the user’s cell phone. Which factor is that?"}, {"id": "2.1-30", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Voice call", "definition": "A phone call provides the token — the computer is talking to you. Similar disadvantages to SMS: phone can be intercepted or forwarded, phone number can be added to another phone.", "scenario": "After the password, an automated call reads a code aloud to the user’s phone. Which factor is that?"}, {"id": "2.1-31", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Time-based one-time password (TOTP)", "definition": "Uses a secret key and the time of day — no incremental counter. Secret key is configured ahead of time. Timestamps are synchronized via NTP and usually increment every 30 seconds.", "scenario": "The phone app shows a six-digit code that changes every 30 seconds based on time. What kind of code is that?"}, {"id": "2.1-32", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "One-time password / passcode (OTP)", "definition": "Use them once and never again — once per session, once per authentication attempt. Keys are based on a secret key and a counter. Token-based authentication: the hash is different every time. Hardware and software tokens available.", "scenario": "The hardware token produces a code you use once and never again for that login. What kind of password is that?"}, {"id": "2.1-33", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Security Assertions Markup Language (SAML)", "definition": "An open standard that lets security systems securely share your identity details so you don’t have to re-enter credentials across different websites.", "scenario": "HR’s website trusts the company login portal so users are not asked for a second password. Which identity standard is sharing that assertion?"}, {"id": "2.1-34", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Single sign-on (SSO)", "definition": "An authentication feature that lets you log in just once to access all your connected apps and services seamlessly.", "scenario": "Staff sign in once in the morning and every SaaS app opens without another password prompt. What feature is that?"}, {"id": "2.1-35", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Just-in-time access", "definition": "A security practice that grants elevated user permissions only for the exact amount of time needed to complete a task, then revokes them automatically.", "scenario": "A tech gets admin rights for 30 minutes to install software, then the rights vanish automatically. What access model is that?"}, {"id": "2.1-36", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Privileged access management (PAM)", "definition": "Tools and policies designed to lock down, monitor, and audit superuser or admin accounts with high-level access.", "scenario": "All domain admin accounts are vaulted, recorded, and checked out only when needed. What kind of management is that?"}, {"id": "2.1-37", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Mobile device management (MDM)", "definition": "IT software that allows administrators to remotely configure, monitor, and secure smartphones and laptops used within an organization.", "scenario": "IT can remotely lock, wipe, and push email settings to every company phone. Which platform is that?"}, {"id": "2.1-38", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Data loss prevention (DLP)", "definition": "Security software that detects and blocks sensitive or confidential information from leaving the organization’s network.", "scenario": "The gateway blocks a spreadsheet of customer SSNs from being emailed outside the company. What control is that?"}, {"id": "2.1-39", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Identity access management (IAM)", "definition": "The overarching framework of policies and technologies that controls who has access to which digital resources.", "scenario": "One system decides who can sign in, what they can open, and tracks those decisions. What framework is that?"}, {"id": "2.1-40", "section": "2.1", "sectionTitle": "Security Measures and Their Purposes", "category": "Logical security", "name": "Directory services", "definition": "A centralized network database that stores, organizes, and manages user accounts, devices, and permissions across an entire organization.", "scenario": "User accounts, computers, and group memberships all live in one central network database. What service is that?"}, {"id": "2.2-0", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Windows Defender Antivirus", "name": "Defender Antivirus", "definition": "The built-in antivirus for Windows — no additional third-party product is required. It lives inside the Windows Security app under Virus & threat protection. The exact label may not read \"Defender Antivirus\"; the name has changed over time (Windows Defender → Windows Defender Antivirus → Microsoft Defender Antivirus).", "scenario": "A Windows 11 PC has no third-party AV installed; you open Windows Security → Virus & threat protection. Which built-in product is that?"}, {"id": "2.2-1", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Windows Defender Antivirus", "name": "Activate/deactivate", "definition": "Don't disable your security protection except for temporary troubleshooting — it increases risk, so make sure you know what you're doing. Defender Antivirus operates in real time. Path: Windows Security app → Virus & threat protection settings → Manage settings → Real-time protection.", "scenario": "Real-time protection was turned off “just for a minute” and never turned back on. What Defender setting was changed?"}, {"id": "2.2-2", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Windows Defender Antivirus", "name": "Update definitions", "definition": "Antivirus is only as good as its latest signatures, so staying up to date matters. Go to Virus & threat protection → Protection updates, and click \"Check for updates.\" Automatic updates are normally configured by default.", "scenario": "Defender missed a brand-new threat until you clicked Check for updates under Protection updates. What did you refresh?"}, {"id": "2.2-3", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Windows Firewall", "name": "Firewall", "definition": "Windows Firewall monitors inbound and outbound network traffic and blocks anything that doesn't match an allowed rule, forming the first line of defense between this PC and the network.", "scenario": "This PC should block unexpected inbound connections from the cafe Wi-Fi. Which Windows feature does that?"}, {"id": "2.2-4", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Windows Firewall", "name": "Activate/deactivate", "definition": "Activating or deactivating a firewall toggles its ability to monitor traffic — turning it off removes protection and leaves the system vulnerable to unauthorized network connections.", "scenario": "A game installer says to turn the firewall off. You know that removes the host’s network filter. What action is that?"}, {"id": "2.2-5", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Windows Firewall", "name": "Port security", "definition": "Port security controls network traffic by selectively opening or closing specific communication ports, to block unauthorized entry and restrict unnecessary network protocols.", "scenario": "Only TCP 443 should be allowed inbound on this workstation; other listeners should be closed. What firewall control is that?"}, {"id": "2.2-6", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Windows Firewall", "name": "Application security", "definition": "Application security allows or blocks specific programs from sending or receiving data across the network — regardless of which port they use.", "scenario": "A chat app is blocked even though the port looks open; you need to allow that specific program through. What kind of firewall rule?"}, {"id": "2.2-7", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Users & Groups", "name": "User and groups", "definition": "Windows controls what a person can do through their account type and group memberships — from a fully locked-down Guest to an unrestricted Administrator.", "scenario": "Rights on this PC come from the account type and which groups the person is in. What are you managing?"}, {"id": "2.2-8", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Users & Groups", "name": "Local vs. Microsoft account", "definition": "A local account stores credentials offline on a single PC and only grants access to that device. A Microsoft account connects your sign-in to cloud services, syncing settings, files, and credentials across multiple devices.", "scenario": "One user signs in only on this PC with a local password; another uses an Outlook.com account that syncs settings. What are you comparing?"}, {"id": "2.2-9", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Users & Groups", "name": "Standard account", "definition": "A Standard account can run applications and change personal settings, but is blocked from installing system-wide software or modifying critical security settings without administrator approval.", "scenario": "The intern can run Office but gets a UAC prompt if they try to install software. Which account type is that?"}, {"id": "2.2-10", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Users & Groups", "name": "Administrator", "definition": "An Administrator account has full, unrestricted control over the operating system — installing software, changing system configuration, and managing permissions for every other user.", "scenario": "You need an account that can join the domain, install drivers, and change any setting. Which type?"}, {"id": "2.2-11", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Users & Groups", "name": "Guest user", "definition": "A Guest account is a restricted, temporary account for casual access. It prevents installing software, changing system settings, or accessing other users' private files.", "scenario": "A visitor needs a throwaway sign-in that cannot see other users’ files or install apps. Which account type?"}, {"id": "2.2-12", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Users & Groups", "name": "Power user", "definition": "Power User is a legacy Windows group with elevated permissions — such as installing legacy applications and running some administrative tools — without full administrator control over the system.", "scenario": "An old Windows group that could install some apps but was not a full admin — you still see it on a study question. Which group?"}, {"id": "2.2-13", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Sign-in Options", "name": "Log-in OS options", "definition": "Windows supports several ways to prove who you are before letting you in — from a classic password to biometrics and passwordless hardware-backed sign-in.", "scenario": "The lock screen offers password, PIN, fingerprint, or face. What category of settings is that?"}, {"id": "2.2-14", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Sign-in Options", "name": "Username and password", "definition": "The traditional authentication method: type a secret string of characters associated with your account name to verify your identity.", "scenario": "The user types their account name and a secret string to get to the desktop. Which sign-in method?"}, {"id": "2.2-15", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Sign-in Options", "name": "Personal identification number (PIN)", "definition": "A short, device-bound numerical code tied specifically to your physical machine — it allows fast login without ever transmitting your main account password over the network.", "scenario": "The laptop unlocks with a short number tied to this device, not the Microsoft account password. What is that?"}, {"id": "2.2-16", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Sign-in Options", "name": "Fingerprint", "definition": "A biometric authentication feature that scans the unique ridges of your finger to quickly verify your identity and unlock your device.", "scenario": "The user rests a finger on the reader to unlock Windows. Which Hello method?"}, {"id": "2.2-17", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Sign-in Options", "name": "Facial recognition", "definition": "A biometric security system that scans your face using specialized infrared or 3D cameras to instantly confirm your identity and grant access.", "scenario": "The IR camera looks at the user’s face to unlock the laptop. Which Hello method?"}, {"id": "2.2-18", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Sign-in Options", "name": "SSO", "definition": "Single sign-on lets you log in once with a single set of credentials and automatically gain access to multiple related applications and websites — no need to type your password again for each one.", "scenario": "After domain login, intranet apps do not ask for a password again. Which sign-in feature?"}, {"id": "2.2-19", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Sign-in Options", "name": "Passwordless/Windows Hello", "definition": "Windows Hello enables passwordless sign-in by replacing text passwords with secure biometrics (facial recognition or fingerprint) or a device-bound PIN, backed by the computer's hardware security chip.", "scenario": "IT wants staff off passwords entirely and onto PIN or biometrics backed by TPM. Which Windows feature?"}, {"id": "2.2-20", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "File & Folder Permissions", "name": "NTFS vs. share permissions", "definition": "Share permissions act like a guard at the front gate, controlling who gets in through the network. NTFS permissions act like individual lockboxes inside the house, controlling access to specific files and subfolders. If either one denies you, you can't get in.", "scenario": "A share allows Everyone, but NTFS on the folder is Read for Staff only — the user cannot write. What rule is in play?"}, {"id": "2.2-21", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "File & Folder Permissions", "name": "File and folder attributes", "definition": "File and folder attributes are metadata flags stored by the file system that define specific operating behaviors and access characteristics — such as read-only, hidden, archived, or encrypted.", "scenario": "A file is marked hidden and read-only in its properties. What are those flags called?"}, {"id": "2.2-22", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "File & Folder Permissions", "name": "Inheritance", "definition": "Permission inheritance is a mechanism where files and subfolders automatically receive (inherit) the access permissions of their parent folder.", "scenario": "A new file in Documents automatically gets the same ACL as the Documents folder. What made that happen?"}, {"id": "2.2-23", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "File & Folder Permissions", "name": "Run as administrator vs. standard user", "definition": "Running as an administrator grants full, unrestricted access to modify system files and settings. A standard user account operates with restricted permissions to prevent unauthorized system-wide changes and protect against malware.", "scenario": "Right-clicking the installer and choosing the elevated option is required; a normal double-click fails. What are you choosing?"}, {"id": "2.2-24", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "File & Folder Permissions", "name": "User Account Control (UAC)", "definition": "A Windows security feature that prevents unauthorized system changes by asking for your permission — or an administrator password — before running programs or making settings changes.", "scenario": "Windows asks “Do you want to allow this app to make changes?” before the installer runs. Which feature is that?"}, {"id": "2.2-25", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Encryption", "name": "BitLocker", "definition": "BitLocker encrypts an entire volume, protecting all of your data including the OS. It's supported on all Windows editions except Home. If you lose your laptop, it doesn't matter without the password — data stays protected even if the physical drive is moved to another computer.", "scenario": "If the laptop is stolen, the whole C: volume should be unreadable without the key. Which feature?"}, {"id": "2.2-26", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Encryption", "name": "BitLocker-To-Go", "definition": "The same BitLocker protection, applied to encrypt removable USB flash drives.", "scenario": "The same full-volume protection needs to apply to a USB stick the user carries. Which feature?"}, {"id": "2.2-27", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Encryption", "name": "Encrypting File System (EFS)", "definition": "EFS encrypts at the file-system level and requires NTFS. It's supported on all Windows editions except Home. It uses your username and password to derive the encryption key — so an administrator password reset will make EFS-encrypted files inaccessible.", "scenario": "Only a few files in a shared folder should be encrypted, not the whole drive, using the user’s credentials. Which feature?"}, {"id": "2.2-28", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Active Directory", "name": "Active Directory", "definition": "Active Directory is a central directory service that lets an organization manage user accounts, computers, and policy from one place, instead of configuring every machine by hand.", "scenario": "All company users and PCs are managed from one directory instead of per-machine accounts. What service is that?"}, {"id": "2.2-29", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Active Directory", "name": "Joining domain", "definition": "Registering a local computer with a central Active Directory domain controller so it can be managed globally and allow users to sign in with domain credentials.", "scenario": "A new laptop must use domain credentials and receive GPOs. What do you do to the PC?"}, {"id": "2.2-30", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Active Directory", "name": "Assigning log-in script", "definition": "Specifying an executable file or script that runs automatically whenever a user signs into the domain, to automate tasks like mapping drives or setting environment variables.", "scenario": "Every morning at logon, a script maps S: and sets a printer. Where is that assigned?"}, {"id": "2.2-31", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Active Directory", "name": "Moving objects within organizational units", "definition": "Relocating user accounts, computers, or groups between organizational units (OUs) to reorganize administrative structure — and change which group policies automatically apply to them.", "scenario": "You drag a user object from the Sales OU to the Finance OU so different policies apply. What did you do?"}, {"id": "2.2-32", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Active Directory", "name": "Assigning home folders", "definition": "Configuring a dedicated private network storage path in a user's account properties, which automatically mounts as a personal drive on logon.", "scenario": "Each user’s private files should land on \\\\files\\users\\%username% and map as a drive. What are you assigning?"}, {"id": "2.2-33", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Active Directory", "name": "Applying Group Policy", "definition": "Enforcing centralized security settings, software deployments, and system configurations across domain users and computers using Group Policy Objects (GPOs).", "scenario": "Password complexity and USB blocking must be forced on every domain PC from one place. What are you applying?"}, {"id": "2.2-34", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Active Directory", "name": "Selecting security groups", "definition": "Adding user or computer objects to specific Active Directory security groups, to streamline granting permissions to network resources like shared folders and printers.", "scenario": "Instead of ACLing the share per person, you add people to Accounting and grant the group access. What are you selecting?"}, {"id": "2.2-35", "section": "2.2", "sectionTitle": "Windows OS Security Settings", "category": "Active Directory", "name": "Configuring folder redirection", "definition": "Diverting standard local user-profile folders (such as Documents or Desktop) to a central network share, so user files are automatically backed up and accessible from any domain machine.", "scenario": "Desktop and Documents should follow the user to any domain PC by living on a share. What did you configure?"}, {"id": "2.3-0", "section": "2.3", "sectionTitle": "Wireless Security Protocols", "category": "Wireless security protocols", "name": "Wi-Fi Protected Access 2 (WPA2)", "definition": "WPA2 is a legacy wireless security protocol introduced in 2004 that uses AES encryption to secure Wi-Fi networks.", "scenario": "The cafe AP still uses the 2004 Wi-Fi standard with AES, not the newest one. Which protocol is that?"}, {"id": "2.3-1", "section": "2.3", "sectionTitle": "Wireless Security Protocols", "category": "Wireless security protocols", "name": "WPA3", "definition": "WPA3 is the modern wireless security standard that provides stronger AES encryption options, improved key exchange security, and individual encryption even on open networks.", "scenario": "You are setting a new AP and want the current Wi-Fi standard with SAE and better open-network privacy. Which protocol?"}, {"id": "2.3-2", "section": "2.3", "sectionTitle": "Wireless Security Protocols", "category": "Wireless security protocols", "name": "Temporal Key Integrity Protocol (TKIP)", "definition": "TKIP is an older encryption protocol designed for WPA as a temporary bridge to replace WEP without requiring new hardware.", "scenario": "An ancient AP only offers the WPA-era encryption that was a stopgap after WEP. Which cipher is that?"}, {"id": "2.3-3", "section": "2.3", "sectionTitle": "Wireless Security Protocols", "category": "Wireless security protocols", "name": "Advanced Encryption Standard (AES)", "definition": "AES is a highly secure symmetric encryption algorithm used by WPA2 and WPA3 that offers significantly stronger protection than TKIP at the cost of higher CPU processing requirements.", "scenario": "WPA2/WPA3 both use this strong symmetric cipher instead of the old TKIP method. Which algorithm?"}, {"id": "2.3-4", "section": "2.3", "sectionTitle": "Wireless Security Protocols", "category": "Authentication methods", "name": "Remote Authentication Dial-in User Service (RADIUS)", "definition": "RADIUS is a widely supported AAA protocol used in enterprise networks to centralize user authentication across 802.1X Wi-Fi, VPNs, and network infrastructure.", "scenario": "Company Wi-Fi and the VPN should both check usernames against the same central AAA server. Which protocol?"}, {"id": "2.3-5", "section": "2.3", "sectionTitle": "Wireless Security Protocols", "category": "Authentication methods", "name": "Terminal Access Controller Access-Control System (TACACS+)", "definition": "TACACS+ is an open-standard remote authentication protocol created as an upgraded alternative to TACACS for managing administrative access to network devices.", "scenario": "Network admins log into switches with a Cisco-friendly AAA protocol that separates authentication from authorization. Which one?"}, {"id": "2.3-6", "section": "2.3", "sectionTitle": "Wireless Security Protocols", "category": "Authentication methods", "name": "Kerberos", "definition": "Kerberos is a ticket-based network authentication protocol that enables single sign-on (SSO) and mutual authentication between clients and servers to prevent replay attacks.", "scenario": "Windows domain logons use tickets so users are not sending a password to every server. Which protocol is that?"}, {"id": "2.3-7", "section": "2.3", "sectionTitle": "Wireless Security Protocols", "category": "Authentication methods", "name": "Multifactor authentication", "definition": "Multifactor authentication verifies user identity by requiring two or more distinct verification credentials, such as passwords and security tokens, before granting wireless network access.", "scenario": "The guest SSID requires a password plus a phone approval. What kind of authentication is that?"}, {"id": "2.4-0", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Trojan", "definition": "Disguises itself as legitimate software to trick users into executing malicious code.", "scenario": "A “free PDF editor” installed fine, then opened a back door. The file looked legitimate. What malware type?"}, {"id": "2.4-1", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Rootkit", "definition": "Gains privileged system-level access while hiding its presence, processes, and files from detection tools.", "scenario": "AV cannot see the infection because it is hiding in the kernel and stripping itself from listings. What type is that?"}, {"id": "2.4-2", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Virus", "definition": "Attaches malicious code to clean files and spreads across systems when host programs execute.", "scenario": "A document macro infects other files when they are opened. What classic malware type is that?"}, {"id": "2.4-3", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Spyware", "definition": "Secretly monitors user activity, gathering sensitive personal data and browser habits without consent.", "scenario": "The browser homepage changed and someone is watching logins without the user knowing. What type is likely?"}, {"id": "2.4-4", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Ransomware", "definition": "Encrypts critical files or locks system access, demanding payment to restore data availability.", "scenario": "The desktop is locked with a note demanding Bitcoin to get the files back. What type is that?"}, {"id": "2.4-5", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Keylogger", "definition": "Captures every keystroke typed on a system to harvest credentials, passphrases, and private messaging data.", "scenario": "Bank passwords were stolen even though the user typed them — something captured the keystrokes. What is that?"}, {"id": "2.4-6", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Boot sector virus", "definition": "Infects the Master Boot Record (MBR) or partition boot sector to load before the operating system boots.", "scenario": "The PC is infected before Windows even starts because the MBR was overwritten. What virus type?"}, {"id": "2.4-7", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Cryptominer", "definition": "Hijacks target system CPU/GPU processing power in the background to mine cryptocurrency without authorization.", "scenario": "The GPU fans scream and electricity spiked; the PC is mining coin in the background. What malware?"}, {"id": "2.4-8", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Stalkerware", "definition": "Intrusive software installed secretly to track real-time location, messages, and calls of a specific individual.", "scenario": "A partner secretly installed an app that tracks location and texts on the other person’s phone. What is that called?"}, {"id": "2.4-9", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Fileless malware", "definition": "Operates entirely within system RAM and native administrative utilities (e.g., PowerShell) without writing files to disk.", "scenario": "No new .exe is on disk; the attack lived in PowerShell and RAM. What malware style is that?"}, {"id": "2.4-10", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Adware", "definition": "Generates unwanted pop-up advertisements on the screen, often bundling with software installations.", "scenario": "Every page is covered in extra pop-up ads after a “toolbar” install. What is that software?"}, {"id": "2.4-11", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Malware and adware types", "name": "Potentially Unwanted Program (PUP)", "definition": "Unintended software installed alongside desired apps that degrades performance or changes browser settings.", "scenario": "The wanted app came with a browser helper that nobody asked for. What is that extra program called?"}, {"id": "2.4-12", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "Recovery Console", "definition": "Command-line environment used to repair system files, fix boot configurations, and remove persistent malware offline.", "scenario": "Windows will not boot cleanly; you need an offline command environment to fix boot files. What are you using?"}, {"id": "2.4-13", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "Endpoint Detection & Response (EDR)", "definition": "Monitors individual host devices continuously for suspicious behavior, providing real-time alerts and remediation options.", "scenario": "Each laptop streams behavior alerts to a console that can isolate a host in real time. What class of tool?"}, {"id": "2.4-14", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "Managed Detection & Response (MDR)", "definition": "Outsourced 24/7 security service providing threat hunting, monitoring, and incident response via dedicated analysts.", "scenario": "The company hires an outside 24/7 SOC to hunt and respond on their endpoints. What service is that?"}, {"id": "2.4-15", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "Extended Detection & Response (XDR)", "definition": "Integrates security data across endpoints, networks, cloud environments, and email systems for unified threat analysis.", "scenario": "Alerts from email, cloud, network, and laptops land in one investigation timeline. What platform style is that?"}, {"id": "2.4-16", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "Antivirus", "definition": "Scans and protects systems using known file signatures to block legacy malware threats like viruses and worms.", "scenario": "You need signature-based scanning for worms and traditional file infectors. What product category?"}, {"id": "2.4-17", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "Anti-malware", "definition": "Detects and remediates complex, modern threats including spyware, Trojans, PUPs, and zero-day variants.", "scenario": "The threat is a PUP/Trojan mix, not a simple virus; you want broader modern coverage. What product category?"}, {"id": "2.4-18", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "Email security gateway", "definition": "Filters inbound and outbound email traffic to block spam, malicious attachments, and phishing links before they reach inboxes.", "scenario": "Bad attachments and phishing links should die before they hit anyone’s inbox. What device or service sits in the mail path?"}, {"id": "2.4-19", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "Software firewalls", "definition": "Filters incoming and outgoing network traffic at the local OS level using defined security rules to block unauthorized connections.", "scenario": "This workstation should filter its own connections even on a hotel LAN. What host-based control?"}, {"id": "2.4-20", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "User education & antiphishing training", "definition": "Teaches users how to identify social engineering traps, suspicious URLs, and malicious file downloads to prevent initial infection.", "scenario": "Users keep clicking fake invoice emails; you schedule a live awareness session. What control is that?"}, {"id": "2.4-21", "section": "2.4", "sectionTitle": "Malware and Adware Types", "category": "Detection, removal, and prevention", "name": "OS reinstallation", "definition": "Erases the primary drive completely and installs a fresh operating system to eliminate deeply persistent infections like rootkits.", "scenario": "A rootkit will not come off; the only safe fix is wiping the disk and loading a known-good OS. What are you doing?"}, {"id": "2.5-0", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Phishing", "definition": "Generic fraudulent emails sent to mass audiences attempting to trick victims into revealing sensitive credentials or clicking malicious links.", "scenario": "Thousands of users get the same fake “reset your mailbox” email with a link. What attack is that?"}, {"id": "2.5-1", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Vishing", "definition": "Voice-based phishing attacks where scammers use phone calls to manipulate victims into providing confidential information.", "scenario": "Someone calling as “IT” asks the receptionist for her password over the phone. What attack is that?"}, {"id": "2.5-2", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Smishing", "definition": "Phishing attacks delivered via SMS text messages containing malicious links or urgent requests for personal data.", "scenario": "A text says the package is held and includes a short link to a fake shipper site. What attack is that?"}, {"id": "2.5-3", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "QR code phishing (quishing)", "definition": "Malicious QR codes placed in physical or digital locations that direct users to credential-harvesting websites when scanned.", "scenario": "A parking-lot sign’s code opens a login page that is not the company’s. What attack is that?"}, {"id": "2.5-4", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Spear phishing", "definition": "Highly targeted phishing campaigns tailored to a specific individual or organization using gathered personal details.", "scenario": "Only the CFO got an email that mentioned yesterday’s vendor by name and a real invoice number. What attack is that?"}, {"id": "2.5-5", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Whaling", "definition": "A specialized form of spear phishing that specifically targets high-profile executives, business owners, or senior leadership.", "scenario": "The CEO is the only target of a fake wire-transfer email written in their style. What attack is that?"}, {"id": "2.5-6", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Shoulder surfing", "definition": "Observing a target’s screen or keyboard directly — either in person or through cameras — to steal sensitive data or passwords.", "scenario": "On the train a stranger watches the user type a PIN. What is that called?"}, {"id": "2.5-7", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Tailgating", "definition": "Following an authorized person through a restricted physical door or entryway without validating credentials.", "scenario": "A stranger holds the door and walks in right behind an employee who badged. What is that called?"}, {"id": "2.5-8", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Impersonation", "definition": "Pretending to be a trusted figure, such as an IT technician or executive, to trick employees into granting access or resetting passwords.", "scenario": "Someone in a vendor shirt asks to be let into the IDF “to check the switch.” They do not work here. What tactic is that?"}, {"id": "2.5-9", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Social engineering attacks", "name": "Dumpster diving", "definition": "Searching through discarded trash, recycling bins, or paper shredder waste to recover sensitive documents or configuration details.", "scenario": "Printed password lists were found in the outdoor recycling bin. How did the attacker get them?"}, {"id": "2.5-10", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Denial of Service (DoS)", "definition": "Overwhelms a target system or service with traffic from a single source to disrupt availability.", "scenario": "One host floods the company website until it is unreachable. What attack is that?"}, {"id": "2.5-11", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Distributed Denial of Service (DDoS)", "definition": "Floods a target system using multiple compromised systems (botnets) from distributed locations to crash services.", "scenario": "Thousands of bots worldwide flood the same website at once. What attack is that?"}, {"id": "2.5-12", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Evil twin", "definition": "A rogue Wi-Fi access point set up to mimic a legitimate network to intercept user traffic and credentials.", "scenario": "A fake “Airport_Free_WiFi” AP sits next to the real one and captures logins. What is that AP called?"}, {"id": "2.5-13", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Zero-day attack", "definition": "An exploit targeting a previously unknown software vulnerability before the vendor releases a patch.", "scenario": "Attackers exploit a bug the vendor has not patched yet — nobody had a signature for it. What kind of attack?"}, {"id": "2.5-14", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Spoofing", "definition": "Falsifying network headers, IP addresses, or sender identities to disguise the origin of malicious traffic or communications.", "scenario": "Packets arrive with a forged source address so replies go to the wrong place. What is that called?"}, {"id": "2.5-15", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "On-path attack", "definition": "Secretly relaying and altering communications between two parties who believe they are directly communicating with each other.", "scenario": "The attacker sits between the user and the bank site, passing traffic both ways and changing it. What attack is that?"}, {"id": "2.5-16", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Brute-force attack", "definition": "Systematically testing every possible character combination until the correct password or key is found.", "scenario": "A script tries every possible password combination against the login page. What attack is that?"}, {"id": "2.5-17", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Dictionary attack", "definition": "Automated password cracking using a predefined list of common words, phrases, and leaked passwords.", "scenario": "A script tries passwords from a list of common words and past leaks. What attack is that?"}, {"id": "2.5-18", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Insider threat", "definition": "Security risks originating from current or former employees, contractors, or business partners with authorized access.", "scenario": "A departing admin copies customer files they still have rights to. What kind of threat is that?"}, {"id": "2.5-19", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "SQL injection (SQLi)", "definition": "Injecting malicious database queries into application entry fields to read or manipulate backend database contents.", "scenario": "A search box on the website is used to dump the users table with a crafted query. What attack is that?"}, {"id": "2.5-20", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Cross-site scripting (XSS)", "definition": "Injecting malicious client-side scripts into trusted web applications to execute in victim browsers and steal session tokens.", "scenario": "A comment field on the site runs script in other visitors’ browsers and steals cookies. What attack is that?"}, {"id": "2.5-21", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Business email compromise (BEC)", "definition": "Hijacking or spoofing executive email accounts to trick finance teams or employees into executing unauthorized wire transfers.", "scenario": "Accounting gets an email that looks like the CEO asking for an urgent wire to a new vendor. What attack is that?"}, {"id": "2.5-22", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Threats", "name": "Supply chain attack", "definition": "Compromising a third-party vendor, software dependency, or service provider to breach target organizations downstream.", "scenario": "A widely used software updater was poisoned, and many customers installed the malware. What attack is that?"}, {"id": "2.5-23", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Vulnerabilities", "name": "Non-compliant systems", "definition": "Devices or systems that violate organizational security policies, baseline standards, or regulatory frameworks.", "scenario": "A PC is missing disk encryption and the required AV even though policy demands both. What is that system called?"}, {"id": "2.5-24", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Vulnerabilities", "name": "Unpatched systems", "definition": "Devices running software with known security flaws due to missing vendor updates and security fixes.", "scenario": "The server is still missing last month’s security rollup for a known CVE. What is that system called?"}, {"id": "2.5-25", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Vulnerabilities", "name": "Unprotected systems", "definition": "Systems lacking basic baseline security controls, such as active antivirus software or properly configured local firewalls.", "scenario": "A kiosk has no AV and the host firewall is off. What is that system called?"}, {"id": "2.5-26", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Vulnerabilities", "name": "End-of-life (EOL)", "definition": "Hardware or software no longer supported or patched by vendors, leaving newly discovered vulnerabilities permanently unaddressed.", "scenario": "The vendor will never ship another patch for this OS version. What status is that?"}, {"id": "2.5-27", "section": "2.5", "sectionTitle": "Social Engineering and Threats", "category": "Vulnerabilities", "name": "Bring Your Own Device (BYOD)", "definition": "Unmanaged personal employee devices connected to enterprise resources without strict organizational security enforcement.", "scenario": "Staff email from personal phones that IT does not manage. What policy model created that risk?"}, {"id": "2.6-0", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Detect and isolate", "name": "Investigate and verify malware symptoms", "definition": "Identify indicators: Look for security alerts, application crashes, unexpected pop-up windows, and system slowdowns or high resource usage.", "scenario": "Pop-ups, a security alert, and a sudden slowdown — you confirm it is actually malware before doing anything else. Which step is that?"}, {"id": "2.6-1", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Detect and isolate", "name": "Quarantine infected system", "definition": "Isolate network connectivity: Disconnect Ethernet cables and disable Wi-Fi/Bluetooth immediately to prevent lateral network movement.", "scenario": "You unplug Ethernet and turn off Wi-Fi so the worm cannot reach the next desk. Which step is that?"}, {"id": "2.6-2", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Detect and isolate", "name": "Disable System Restore in Windows Home", "definition": "Prevent reinfection: Turn off System Protection in System Properties.", "scenario": "You turn off System Protection so malware cannot hide in an old restore point. Which step is that?"}, {"id": "2.6-3", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Remove and scan", "name": "Remediate infected systems", "definition": "Quarantine or delete files: Isolate malicious binaries into protected quarantine folders so they cannot execute, or delete them outright.", "scenario": "The scanner isolates the bad files so they cannot run, or deletes them. Which step is that?"}, {"id": "2.6-4", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Remove and scan", "name": "Update anti-malware software", "definition": "Update engine and definitions: Ensure signature files and scanning engines are current so new variants can be recognized.", "scenario": "Before the deep scan you download the newest signatures. Which step is that?"}, {"id": "2.6-5", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Remove and scan", "name": "Scan and removal techniques", "definition": "Use Safe Mode: Boot into Safe Mode to load only minimal OS drivers and prevent non-essential startup items or malware processes from launching.", "scenario": "You reboot to Safe Mode so only minimal drivers load, then scan. Which step is that?"}, {"id": "2.6-6", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Recover and prevent", "name": "Reimage / reinstall", "definition": "Wipe and reinstall: Perform a clean OS installation or restore from a known-good system image if malware cannot be guaranteed 100% removed.", "scenario": "You cannot be sure the rootkit is gone, so you wipe and load a known-good image. Which step is that?"}, {"id": "2.6-7", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Recover and prevent", "name": "Schedule scans and run updates", "definition": "Automate defense: Set up scheduled antivirus scans and signature updates in the security software or via Windows Task Scheduler.", "scenario": "After cleanup, nightly scans and signature updates are set on a schedule. Which step is that?"}, {"id": "2.6-8", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Recover and prevent", "name": "Enable System Restore and create a restore point in Windows Home", "definition": "Re-enable protection: Turn System Protection back on once the machine is fully verified clean.", "scenario": "The PC is clean, so you turn System Protection back on and make a fresh restore point. Which step is that?"}, {"id": "2.6-9", "section": "2.6", "sectionTitle": "Malware Investigation and Remediation", "category": "Recover and prevent", "name": "Educate the end user", "definition": "Direct training: Conduct one-on-one user awareness sessions on safe browsing habits and phishing identification.", "scenario": "You sit with the user and show them how the fake invoice email got in. Which last step is that?"}, {"id": "2.7-0", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Data-at-rest encryption", "name": "Full-disk encryption", "definition": "Encrypts the entire storage drive to protect data-at-rest from unauthorized physical extraction.", "scenario": "The whole laptop disk should be unreadable if the drive is pulled out. Which encryption style?"}, {"id": "2.7-1", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Data-at-rest encryption", "name": "File system encryption", "definition": "Encrypts specific individual files and folders for targeted data protection.", "scenario": "Only the Contracts folder needs to be encrypted, not the entire volume. Which encryption style?"}, {"id": "2.7-2", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Data-at-rest encryption", "name": "Removable media security", "definition": "Protects external media like USB flash drives from unauthorized access.", "scenario": "A USB stick of HR files must stay protected if it is left on a train. What are you securing?"}, {"id": "2.7-3", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Data-at-rest encryption", "name": "Key backups", "definition": "Secure key copies must be maintained (often integrated into Active Directory) to ensure data recovery options remain available.", "scenario": "BitLocker recovery keys are stored in AD so a forgotten PIN does not mean lost data. What are you keeping?"}, {"id": "2.7-4", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Password considerations", "name": "Length", "definition": "Enforce strong passwords with a minimum of 8 characters — or use multi-word passphrases.", "scenario": "Policy says passwords must be at least 14 characters or a long passphrase. Which password rule?"}, {"id": "2.7-5", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Password considerations", "name": "Character types & complexity", "definition": "Combine uppercase letters, lowercase letters, numbers, and special characters while avoiding single or obvious words to maximize entropy.", "scenario": "Passwords must mix upper, lower, digits, and symbols — not a single dictionary word. Which rule?"}, {"id": "2.7-6", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Password considerations", "name": "Uniqueness", "definition": "Enforce unique passwords across accounts and utilize password history settings to prevent reusing old credentials.", "scenario": "The same password cannot be reused on VPN, email, and the laptop. Which rule?"}, {"id": "2.7-7", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Password considerations", "name": "Expiration", "definition": "Set age and expiration policies (e.g., 30, 60, or 90 days; 15 days or weekly for critical systems) so passwords automatically invalidate after a set duration.", "scenario": "Domain passwords die every 90 days and must be changed. Which policy is that?"}, {"id": "2.7-8", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "BIOS/UEFI passwords", "name": "Supervisor / administrator password", "definition": "Prevents unauthorized users from modifying low-level system settings or BIOS/UEFI configurations.", "scenario": "Nobody should enter firmware setup without a password, even if they can boot Windows. Which BIOS password?"}, {"id": "2.7-9", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "BIOS/UEFI passwords", "name": "User password", "definition": "Requires a valid password before the operating system is permitted to boot.", "scenario": "The PC should not even start Windows until a firmware password is entered. Which BIOS password?"}, {"id": "2.7-10", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "End-user best practices", "name": "Use screensaver locks", "definition": "Require passwords to unlock screensavers that automatically engage after defined idle timeouts.", "scenario": "After 10 minutes idle, the screen should require a password to come back. What should you use?"}, {"id": "2.7-11", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "End-user best practices", "name": "Log off / lock desktop", "definition": "Secure workstations immediately when walking away to prevent unauthorized physical access.", "scenario": "The user is walking to lunch and should secure the session immediately. What should they do?"}, {"id": "2.7-12", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "End-user best practices", "name": "Secure critical hardware", "definition": "Protect laptops and physical assets using cable locks and secure mounting.", "scenario": "A laptop in the lobby is cabled to the desk so it cannot walk away. What practice is that?"}, {"id": "2.7-13", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "End-user best practices", "name": "Secure PII & passwords", "definition": "Position monitors away from hallways or windows, use privacy filters, remain aware of surroundings, and refrain from writing credentials on sticky notes.", "scenario": "The monitor faces a hallway; you add a privacy filter and ban sticky-note passwords. What are you protecting?"}, {"id": "2.7-14", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "End-user best practices", "name": "Use password managers", "definition": "Encrypt and store unique credentials across all accounts in a single database, with support for multi-factor tokens and centralized enterprise recovery.", "scenario": "Staff should store unique site passwords in an encrypted vault, not in a browser or notebook. What should they use?"}, {"id": "2.7-15", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Account management", "name": "Restrict user permissions", "definition": "Follow the principle of least privilege, audit user rights, and assign permissions to groups rather than managing per-user rights directly.", "scenario": "The intern does not need to install software; you remove them from Administrators. What are you restricting?"}, {"id": "2.7-16", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Account management", "name": "Restrict log-in times", "definition": "Limit user authentication strictly to active working hours and block after-hours activity.", "scenario": "The night-shift account should not be able to log on at 10 a.m. What restriction is that?"}, {"id": "2.7-17", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Account management", "name": "Disable guest account", "definition": "Remove or disable built-in Guest, root, or unnecessary default system accounts to reduce potential entry points.", "scenario": "The built-in Guest account is still enabled on a kiosk. What should you do to it?"}, {"id": "2.7-18", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Account management", "name": "Use failed attempts lockout", "definition": "Configure account lockout thresholds to lock accounts or reboot systems after repeated failed authentication attempts, blocking online brute-force attacks.", "scenario": "After five bad passwords the account freezes for 30 minutes. Which setting is that?"}, {"id": "2.7-19", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Account management", "name": "Use timeout / screen lock", "definition": "Enforce automatic desktop locking after designated periods of user inactivity.", "scenario": "If someone walks away, the desktop should lock by itself after a few minutes. Which setting?"}, {"id": "2.7-20", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Account management", "name": "Apply account expiration dates", "definition": "Automatically disable accounts assigned to temporary workers, vendors, or contractors on a predetermined date.", "scenario": "A contractor’s domain account should stop working on their last day automatically. What do you set?"}, {"id": "2.7-21", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Change default administrator account/password", "name": "Rename default usernames", "definition": "Change stock administrator accounts (e.g., admin) to unique names.", "scenario": "The local Administrator account is still named Administrator. What should you change?"}, {"id": "2.7-22", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Change default administrator account/password", "name": "Update default passwords", "definition": "Replace default credentials immediately across all OS installations and network devices to disrupt automated brute-force scripts.", "scenario": "The new AP still uses admin/admin from the sticker. What should you change first?"}, {"id": "2.7-23", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Disable AutoRun", "name": "Registry controls", "definition": "Disable autorun.inf execution via the system registry on supported Windows environments.", "scenario": "A registry policy stops autorun.inf from launching when a disc is inserted. What did you configure?"}, {"id": "2.7-24", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Disable AutoRun", "name": "AutoPlay settings", "definition": "Configure device behavior via Settings → Bluetooth & devices → AutoPlay (e.g., setting default actions to “Take no action”) to prevent automatic execution of media content.", "scenario": "Settings → AutoPlay is set to Take no action for removable drives. What did you change?"}, {"id": "2.7-25", "section": "2.7", "sectionTitle": "Encryption and Security Best Practices", "category": "Disable unused services", "name": "Attack surface reduction", "definition": "Audit background services installed by the OS or third-party applications and disable any unneeded services to close open entry points and protect against external breaches.", "scenario": "You turn off unused print spooler and remote registry services to close extra doors. What are you doing?"}, {"id": "2.8-0", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Hardening techniques", "name": "Device encryption", "definition": "Encrypts all device data while the phone retains the decryption key.", "scenario": "If the phone is stolen, the flash storage should be unreadable without the device key. What must be on?"}, {"id": "2.8-1", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Hardening techniques", "name": "Screen locks", "definition": "Restricts physical access to a device using various authenticators:", "scenario": "The phone should require a PIN or biometric before the home screen appears. What should you enable?"}, {"id": "2.8-2", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Hardening techniques", "name": "Configuration profiles", "definition": "Pre-defined system configurations pushed to devices via Mobile Device Management (MDM) platforms — such as Microsoft Intune or Apple Configurator — to streamline setup, corporate email deployment, and security settings like mandatory lock screens and encryption.", "scenario": "Sales phones all get the same email, Wi-Fi, and passcode rules from Intune in one package. What are those packages called?"}, {"id": "2.8-3", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Patch management", "name": "OS updates", "definition": "Regular operating system updates that deliver new features, stability fixes, and critical security patches to prevent vulnerabilities.", "scenario": "The iPhone is a year behind on iOS and has known CVEs. What is missing?"}, {"id": "2.8-4", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Patch management", "name": "Application updates", "definition": "Ongoing updates for installed applications to maintain current feature sets and resolve security bugs.", "scenario": "The banking app vendor shipped a security fix in the store. What should the user install?"}, {"id": "2.8-5", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Endpoint security software", "name": "Antivirus & anti-malware", "definition": "Protects against malicious software.", "scenario": "Company phones need a scanner for malicious apps, not just the OS sandbox. What software category?"}, {"id": "2.8-6", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Endpoint security software", "name": "Content filtering", "definition": "Restricts device access to unauthorized or hazardous websites and applications.", "scenario": "MDM should block gambling and known-bad websites on the work phone. What control is that?"}, {"id": "2.8-7", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Endpoint security software", "name": "Firewalls", "definition": "Mobile operating systems generally do not include native firewalls, as most network traffic is outbound. Third-party mobile firewall apps exist (primarily for Android), while enterprise network firewalls regulate application traffic centrally.", "scenario": "Android can get a third-party app that filters traffic; iOS mostly relies on the network edge. What control is being discussed?"}, {"id": "2.8-8", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Locator applications & remote wipes", "name": "Locator applications", "definition": "Utilizes built-in GPS and location features to locate lost or stolen devices on a map, sound alerts, or display contact messages remotely.", "scenario": "A lost tablet should play a sound and show on a map. Which feature?"}, {"id": "2.8-9", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Locator applications & remote wipes", "name": "Remote wipes", "definition": "Allows administrators or owners to wipe all data remotely if a lost device cannot be recovered.", "scenario": "The stolen phone cannot be found; IT erases it from the MDM console. Which feature?"}, {"id": "2.8-10", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Failed log-in attempt restrictions", "name": "iOS", "definition": "Automatically erases all local data after 10 consecutive failed passcode attempts.", "scenario": "After ten wrong passcodes, this iPhone will erase itself. Which platform’s behavior is that?"}, {"id": "2.8-11", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Failed log-in attempt restrictions", "name": "Android", "definition": "Locks the device following repeated failed attempts, requiring a Google login or triggering a full device wipe.", "scenario": "After too many wrong PINs, this phone locks and wants the Google account, or it wipes. Which platform?"}, {"id": "2.8-12", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Policies and procedures", "name": "MDM (Mobile Device Management)", "definition": "Provides centralized administration for mobile endpoints, enabling remote control over the whole device or an enterprise partition, enforcing access controls, and setting policies for apps, cameras, and data.", "scenario": "IT needs one console to push apps, require encryption, and wipe phones. Which product category?"}, {"id": "2.8-13", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Policies and procedures", "name": "BYOD vs. corporate-owned", "definition": "Policies to manage employee-owned (BYOD) and company-owned endpoints under uniform organizational security rules.", "scenario": "Some staff use personal phones for mail; others get company-owned devices. What policy choice is that?"}, {"id": "2.8-14", "section": "2.8", "sectionTitle": "Mobile Device Hardening", "category": "Policies and procedures", "name": "Profile security requirements", "definition": "Mandates access control standards across deployment profiles, such as forcing minimum screen lock criteria and PIN complexity.", "scenario": "Every enrollment profile requires a 6-digit PIN and encryption. What are those profile rules called?"}, {"id": "2.9-0", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Physical destruction methods", "name": "Drilling / hammering", "definition": "Drilling holes straight through magnetic platters or physically breaking the drive. Offers a quick, simple way to render media unusable.", "scenario": "You put holes through the platters with a drill so the disk can never spin again. Which destruction method?"}, {"id": "2.9-1", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Physical destruction methods", "name": "Shredding", "definition": "Uses heavy industrial machinery to grind drives into tiny fragments for complete destruction.", "scenario": "Drives go into an industrial grinder and come out as metal bits. Which method?"}, {"id": "2.9-2", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Physical destruction methods", "name": "Degaussing", "definition": "Applies high-power electromagnetic fields to remove magnetic domains. Completely erases data and destroys hard drive functionality.", "scenario": "A strong magnetic field wipes the platters and kills the drive electronics. Which method?"}, {"id": "2.9-3", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Physical destruction methods", "name": "Incineration", "definition": "Subjects drive hardware to extreme heat to burn and destroy storage components.", "scenario": "Retired disks are burned in a high-heat furnace. Which method?"}, {"id": "2.9-4", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Recycling or repurposing methods", "name": "File-level overwriting", "definition": "Deletes specific files using tools like Windows Sysinternals Sdelete, though remaining unallocated data remains untouched.", "scenario": "You only need to destroy one confidential file, not the whole disk, with a secure-delete tool. Which method?"}, {"id": "2.9-5", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Recycling or repurposing methods", "name": "Whole-drive wiping", "definition": "Software utilities like DBAN (Darik’s Boot and Nuke) overwrite all storage sectors, securely wiping data so the drive can safely be repurposed.", "scenario": "The whole HDD will be reused in a lab after a boot-and-nuke overwrite of every sector. Which method?"}, {"id": "2.9-6", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Recycling or repurposing methods", "name": "Low-level formatting", "definition": "Performed at the factory by the manufacturer. Generally not recommended or performed by end users.", "scenario": "A factory process that end users should not run on a modern drive. Which format type is that?"}, {"id": "2.9-7", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Recycling or repurposing methods", "name": "Standard formatting — quick format", "definition": "Clears the Master File Table (MFT) and sets up a new file system, but leaves the underlying data intact where software recovery tools can still retrieve it.", "scenario": "You format the volume in seconds; recovery tools can still find the old files. Which format?"}, {"id": "2.9-8", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Recycling or repurposing methods", "name": "Standard formatting — regular format", "definition": "Overwrites every drive sector with zeros, preventing data recovery. This process has been the default behavior since Windows Vista.", "scenario": "You format and Windows writes zeros to every sector so files are not recoverable. Which format?"}, {"id": "2.9-9", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Outsourcing concepts", "name": "Third-party vendors", "definition": "Organizations frequently contract specialized third-party vendors equipped with industrial destroyers, drills, and degaussers to manage high-volume disposal.", "scenario": "The company hires a specialist with industrial shredders instead of destroying disks in-house. Who is that?"}, {"id": "2.9-10", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Outsourcing concepts", "name": "Certificate of destruction", "definition": "Service providers supply an official certificate to provide a verified paper trail confirming how and when specific hardware serial numbers were destroyed.", "scenario": "The vendor gives you a signed paper listing serial numbers and the date they were destroyed. What document is that?"}, {"id": "2.9-11", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Regulatory requirements & data security", "name": "Legal compliance", "definition": "Highly regulated sectors — including healthcare, financial services, and research organizations — are bound by legal mandates and local policies requiring complete physical destruction of retired storage media.", "scenario": "HIPAA and similar rules say these disks cannot just be thrown in the dumpster. What requirement is that?"}, {"id": "2.9-12", "section": "2.9", "sectionTitle": "Data Destruction and Sanitization", "category": "Regulatory requirements & data security", "name": "Data leakage risks", "definition": "Inadequate sanitization leaves residual PII (Personally Identifiable Information), corporate emails, and confidential files on secondary markets (e.g., eBay), exposing organizations to regulatory fines and privacy breaches.", "scenario": "Old laptops showed up on an auction site with patient records still on them. What risk materialized?"}, {"id": "2.10-0", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Router settings", "name": "Change default passwords", "definition": "Access points ship with publicly known default credentials. Change the default admin password immediately to prevent unauthorized users from taking full administrative control of the device.", "scenario": "The new SOHO router still uses the password printed in the manual. What should you change first?"}, {"id": "2.10-1", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Router settings", "name": "IP filtering", "definition": "Restrict or grant network access by defining specific IP address ranges.", "scenario": "Only the accounting VLAN’s addresses should reach the printer; other subnets should not. What filter is that?"}, {"id": "2.10-2", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Router settings", "name": "Firmware updates", "definition": "Maintain SOHO appliances by regularly applying manufacturer updates. Installing the latest firmware patches security vulnerabilities, fixes bugs, and adds missing features.", "scenario": "The AP vendor released a fix for a WAN-side bug. What should you apply?"}, {"id": "2.10-3", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Router settings", "name": "Content filtering", "definition": "Inspect network traffic by URL or website category. Use content filters to enforce corporate policies, manage parental controls/NSFW content, prevent sensitive data leaks, and stop malicious software via integrated anti-virus features.", "scenario": "The office firewall should block known-bad sites and social media by category. What feature is that?"}, {"id": "2.10-4", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Router settings", "name": "Physical placement / secure locations", "definition": "Lock physical routers, switches, and servers in a secure room to prevent physical tampering. Mount wireless access points high (such as above ceiling tiles) to maximize coverage — keeping in mind that hard-to-reach locations make power cycling more difficult.", "scenario": "The wireless AP is on a shelf anyone can unplug. You move it above the ceiling in a locked closet. What are you fixing?"}, {"id": "2.10-5", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Router settings", "name": "Universal Plug and Play (UPnP)", "definition": "UPnP permits devices and internal applications to open inbound firewall ports automatically without administrator approval.", "scenario": "A game console opened inbound ports on the firewall by itself with no admin click. Which feature allowed that?"}, {"id": "2.10-6", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Router settings", "name": "Screened subnet", "definition": "Place public-facing resources (like web servers) in a screened subnet between the internet and the internal network. Creates an isolated security layer so external access to public services doesn’t compromise private internal systems.", "scenario": "The public web server sits on its own segment between the internet and the LAN. What is that segment called?"}, {"id": "2.10-7", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Router settings", "name": "Configure secure management access", "definition": "Enforce strong authentication credentials and multi-factor authentication for administrative logins. Restrict management connections to local LAN IPs only and disable remote WAN management access completely.", "scenario": "Router admin should only work from the LAN, with MFA, never from the WAN. What are you configuring?"}, {"id": "2.10-8", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Wireless specific", "name": "Changing the service set identifier (SSID)", "definition": "Replace default factory network names (such as “NETGEAR” or “LINKSYS”) with a non-obvious identifier to avoid signaling your equipment type to outsiders.", "scenario": "The SSID is still LINKSYS. You rename it so it does not advertise the hardware. What did you change?"}, {"id": "2.10-9", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Wireless specific", "name": "Disabling SSID broadcast", "definition": "Hiding an SSID stops the router from broadcasting its name publicly. However, this only relies on security through obscurity — wireless analysis tools easily discover hidden SSIDs.", "scenario": "You hide the network name so it does not show in the list — knowing a scanner can still find it. What did you disable?"}, {"id": "2.10-10", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Wireless specific", "name": "Encryption settings", "definition": "Choose an appropriate wireless encryption standard:", "scenario": "The guest SSID is still on an outdated wireless cipher. You switch it to WPA3. What settings are those?"}, {"id": "2.10-11", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Wireless specific", "name": "Configuring guest access", "definition": "Enable isolated guest networks to keep visitors off the primary LAN, or use guest networks to segregate IoT devices and lab environments. Always protect guest networks using WPA2 or WPA3 encryption.", "scenario": "Visitors get internet on a separate SSID that cannot see the office file server. What did you configure?"}, {"id": "2.10-12", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Firewall settings", "name": "Disabling unused ports", "definition": "Administratively turn off unused physical switch ports in open areas (like conference rooms or break rooms) to stop unauthorized physical hookups. Alternatively, deploy Network Access Control (802.1X NAC) to block network traffic until a device authenticates.", "scenario": "The unused Ethernet jack in the lobby should not pass traffic if someone plugs in. What do you disable?"}, {"id": "2.10-13", "section": "2.10", "sectionTitle": "Router and Firewall Settings", "category": "Firewall settings", "name": "Port forwarding / mapping", "definition": "Configure Destination NAT (Static NAT) to permanently direct external inbound traffic from a public IP and port to an internal server’s private IP and port. Provides persistent 24/7 internet access to internally hosted applications like web servers, game servers, or security systems.", "scenario": "Outside users need the security camera NVR on a private IP. You map a public port to it. What is that called?"}, {"id": "2.11-0", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Browser download and installation", "name": "Trusted sources", "definition": "Obtain software exclusively from official vendor sites to prevent downloading malware embedded in third-party installers. Avoid clicking links in emails or external pages — type the URL directly into the address bar.", "scenario": "Staff should get Chrome only from Google’s site, typed in the address bar, not from an email link. What kind of source is that?"}, {"id": "2.11-1", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Browser download and installation", "name": "Untrusted sources", "definition": "Avoid downloading applications from random websites, file-sharing platforms, or links embedded in unsolicited emails.", "scenario": "A “free codec” site bundled a browser that is not from the vendor. What kind of source is that?"}, {"id": "2.11-2", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Browser download and installation", "name": "Hashing", "definition": "Install a hash-checking application (CLI or GUI) to calculate the file’s hash value (e.g., SHA-256). Compare the calculated hash against the official value published on the vendor’s download site to verify file integrity.", "scenario": "You SHA-256 the installer and match it to the vendor’s published digest before running it. What check is that?"}, {"id": "2.11-3", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Browser patching", "name": "Updating", "definition": "Keep browsers updated to apply critical security patches. Updates are frequently integrated directly into the OS update manager or automatically installed within the browser.", "scenario": "The browser is months behind and missing XSS fixes. What should you do?"}, {"id": "2.11-4", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Extensions and plug-ins", "name": "Trusted sources", "definition": "Install add-ons exclusively from official repositories like the Chrome Web Store or Microsoft Store.", "scenario": "Extensions should come from the Chrome Web Store, not a random ZIP. What kind of source?"}, {"id": "2.11-5", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Extensions and plug-ins", "name": "Untrusted sources", "definition": "Avoid third-party sites or unverified software installers, which represent a significant attack vector capable of credential theft, keylogging, and data exfiltration.", "scenario": "A toolbar installer from a file-share is offering a “helpful” add-on. What kind of source is that?"}, {"id": "2.11-6", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Password managers", "name": "Password vaults", "definition": "Store credentials inside encrypted vaults rather than plain browser stores.", "scenario": "Passwords should live in an encrypted vault, not saved in plaintext in the browser. What are those vaults?"}, {"id": "2.11-7", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Password managers", "name": "Unique passwords", "definition": "Use password managers to generate unique, complex passwords per site to eliminate credential reuse risks.", "scenario": "The same password was used on email and shopping; a manager wants a unique one per site. What rule is that?"}, {"id": "2.11-8", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Secure connections / sites — valid certificates", "name": "Certificate inspection", "definition": "Inspect security alerts regarding untrusted root authorities, expired certificates, or domain mismatches. Verify certificate details, including issuer and subject common names. Ensure local system date and time settings are correct to prevent false certificate invalidation.", "scenario": "HTTPS warns that the cert is expired and the name does not match. What should you inspect?"}, {"id": "2.11-9", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Settings configuration", "name": "Pop-up blocker", "definition": "Keep pop-up blockers enabled by default to block unwanted notifications and malicious windows. Disable temporarily only for specific troubleshooting, or add site-specific allow/block rules.", "scenario": "Malicious extra windows keep opening; you re-enable the feature that stops them. What is that feature?"}, {"id": "2.11-10", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Settings configuration", "name": "Clearing browsing data", "definition": "Manually or automatically remove stored browsing history, saved passwords, and downloaded file lists from browser settings.", "scenario": "A shared kiosk should not keep history, saved passwords, or the download list. What do you clear?"}, {"id": "2.11-11", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Settings configuration", "name": "Clearing cache", "definition": "Delete locally stored web assets, images, and cookies to free space and clear stale or sensitive site data.", "scenario": "A site looks broken after an update; you delete stored images and cookies for a clean pull. What did you clear?"}, {"id": "2.11-12", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Settings configuration", "name": "Private-browsing mode", "definition": "Launch private windows to prevent session data, history, download lists, and caches from being retained locally once closed.", "scenario": "The user wants this session’s history gone when the window closes. Which mode?"}, {"id": "2.11-13", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Settings configuration", "name": "Sign-in / browser data synchronization", "definition": "Sign into the browser profile to synchronize history, favorites, settings, and extensions across multiple devices.", "scenario": "Favorites and extensions should follow the user from the desktop to the laptop. What did they turn on?"}, {"id": "2.11-14", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Settings configuration", "name": "Ad blockers", "definition": "Configure tracking prevention and ad-blocking levels (Basic, Balanced, Strict) within privacy settings to restrict site tracking across visits.", "scenario": "Tracking ads follow the user across news sites; you raise the privacy slider. What did you enable?"}, {"id": "2.11-15", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Settings configuration", "name": "Proxy", "definition": "Configure explicit proxy IP addresses and port numbers under OS or browser network settings to route traffic through intermediary servers for caching, URL filtering, and content scanning. Transparent proxies function inline without client-side setup.", "scenario": "All browser traffic must go through the company’s filtering server on port 8080. What did you configure?"}, {"id": "2.11-16", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Settings configuration", "name": "Secure DNS", "definition": "Enable DNS over HTTPS (DoH) in browser advanced settings to encrypt plaintext DNS queries, preventing external observers from monitoring requested FQDNs.", "scenario": "DNS lookups should be encrypted so the coffee-shop owner cannot see which sites are opened. What setting is that?"}, {"id": "2.11-17", "section": "2.11", "sectionTitle": "Browser Security and Configuration", "category": "Browser feature management", "name": "Enable / disable", "definition": "Access browser management interfaces (e.g., chrome://extensions or browser settings) to manually enable, disable, or remove specific plug-ins, extensions, or native browser capabilities to minimize exposure to security risks.", "scenario": "A risky plug-in is turned off in chrome://extensions to shrink the attack surface. What are you doing?"}], "total": 231};
